from collections import defaultdict

def aggregate(rows, key, value):
    out = defaultdict(lambda: {'count': 0, 'total': 0})
    for r in rows:
        if key not in r:
            continue
        g = out[r[key]]
        g['count'] += 1
        v = r.get(value)
        if v is not None:
            g['total'] += v
    return dict(out)

